/* @lc app=leetcode id=2258 lang=kotlin */ class Solution { fun dirs(p: IntArray, g: Array<IntArray>) = listOf(intArrayOf(1, 0), intArrayOf(-1, 0), intArrayOf(0, 1), intArrayOf(0, -1)).map { intArrayOf(p[0] + it[0], p[1] + it[1]) }.filter { it[0] in g.indices && it[1] in g[0].indices && g[it[0]][it[1]] != 2 } fun st(a: Array<IntArray>, p: IntArray, v: Int) { a[p[0]][p[1]] = v } fun mk(s: Array<BooleanArray>, p: IntArray) = true.also { s[p[0]][p[1]] = true } fun fireT(g: Array<IntArray>): Array<IntArray> = Array(g.size) { i -> IntArray(g[0].size) { j -> if (g[i][j] == 1) 0 else Int.MAX_VALUE / 2 } }.also { fr -> generateSequence(g.indices.flatMap { i -> g[0].indices.filter { g[i][it] == 1 }.map { intArrayOf(i, it) } } to 0) { (f, d) -> f.flatMap { dirs(it, g) }.filter { fr[it[0]][it[1]] == Int.MAX_VALUE / 2 }.distinctBy { it[0] * g[0].size + it[1] }.onEach { st(fr, it, d + 1) }.takeIf { it.isNotEmpty() }?.let { it to d + 1 } }.count() } fun check(g: Array<IntArray>, fire: Array<IntArray>, t: Int): Boolean = fire[0][0] > t && Array(g.size) { BooleanArray(g[0].size) }.let { seen -> mk(seen, intArrayOf(0, 0)).let { generateSequence(listOf(intArrayOf(0, 0)) to 0) { (f, d) -> f.flatMap { dirs(it, g) }.filter { c -> g[c[0]][c[1]] == 0 && !seen[c[0]][c[1]] && (t + d + 1).let { T -> T < fire[c[0]][c[1]] || (c[0] == g.size - 1 && c[1] == g[0].size - 1 && T <= fire[c[0]][c[1]]) } }.distinctBy { it[0] * g[0].size + it[1] }.onEach { mk(seen, it) }.takeIf { it.isNotEmpty() }?.let { it to d + 1 } }.any { (f, _) -> f.any { it[0] == g.size - 1 && it[1] == g[0].size - 1 } } } } fun maximumMinutes(grid: Array<IntArray>): Int = fireT(grid).let { fr -> (grid.size * grid[0].size).let { mn -> if (!check(grid, fr, 0)) -1 else if (check(grid, fr, mn)) 1_000_000_000 else generateSequence(0 to mn) { (lo, hi) -> if (lo >= hi) null else ((lo + hi + 1) / 2).let { mid -> if (check(grid, fr, mid)) mid to hi else lo to mid - 1 } }.last().first } } }